descriptor.templateCss:
#container {
    overflow: auto;
}

.tbDatasource-container {
    margin: 5px;
    padding: 8px;
}

.tbDatasource-title {
    font-size: 1.200rem;
    font-weight: 500;
    padding-bottom: 10px;
}

.tbDatasource-table {
    width: 100%;
    box-shadow: 0 0 10px #ccc;
    border-collapse: collapse;
    white-space: nowrap;
    font-size: 1.000rem;
    color: #757575;
}

.tbDatasource-table td {
    position: relative;
    border-top: 1px solid rgba(0, 0, 0, 0.12);
    border-bottom: 1px solid rgba(0, 0, 0, 0.12);
    padding: 0px 18px;
    box-sizing: border-box;
}

descriptor.controllerScript:
self.onInit = function () {
    var TARGET_STATE = 'gep_1';                      // id of the machine view state <-- set yours
    var SHOP_URL = 'https://nextgennitrogen.hu';

    var btn = self.ctx.$container[0].querySelector('.gb-btn');
    var ready = false;

    // the label is the widget's title (e.g. "Gép #1")
    function label() {
        var cfg = self.ctx.widgetConfig;
        return (cfg && cfg.title) || self.ctx.widgetTitle || 'Gép';
    }

    // the device found by the alias, or null if the machine isn't added yet
    function device() {
        var ds = self.ctx.datasources && self.ctx.datasources[0];
        return (ds && ds.entityId) ? ds : null;
    }

    function refresh() {
        var d = device();
        if (d) {
            btn.textContent = label();
            btn.className = 'gb-btn';
        } else if (ready) {
            btn.textContent = '+';
            btn.className = 'gb-btn gb-plus';
        } else {
            btn.textContent = '…';
        }
    }

    btn.addEventListener('click', function () {
        var d = device();
        if (!d) {
            window.open(SHOP_URL, '_blank', 'noopener');
            return;
        }
        self.ctx.stateController.openState(TARGET_STATE, {
            entityId: { id: d.entityId, entityType: d.entityType || 'DEVICE' },
            entityName: d.entityName || ''
        }, false);
    });

    self.onDataUpdated = refresh;
    self.onEditModeChanged = refresh;
    setTimeout(function () { ready = true; refresh(); }, 1500);   // wait for the alias before showing "+"
    refresh();
    
};

self.onDestroy = function () {};

self.typeParameters = function () {
    return {
        datasourcesOptional: true,
        dataKeysOptional: true
    };
};
